  "query": "SELECT Id, Name, Account__r.Name, Account__r.Id, Line_of_Business__c, Expiration_Date__c, Annual_Premium__c, Status__c FROM Policy__c WHERE Status__c IN ('Active','Pending Renewal') AND Expiration_Date__c >= TODAY AND Expiration_Date__c <= NEXT_N_DAYS:60 ORDER BY Expiration_Date__c LIMIT 50"
